#include <bits/stdc++.h>
using namespace std;int main(){int M=1000000,S=3000000;vector<bool>isp(S+1,true);isp[0]=isp[1]=0;vector<int>ps;for(int i=2;i<=S;i++)if(isp[i]){ps.push_back(i);if(1LL*i*i<=S)for(long long j=1LL*i*i;j<=S;j+=i)isp[j]=0;}vector<int>seen(M+1);int st=0,mx=0;vector<int>C(1),Lv(M+1);for(int m=9;m<=M;m+=2){if(isp[m])continue;int z=m;bool sf=true;for(int p:ps){if(1LL*p*p>z)break;if(z%p==0){z/=p;if(z%p==0){sf=false;break;}while(z%p==0)z/=p;}}if(!sf)continue;++st;long long x=1;int L=0;for(int p:ps){x=x*(p%m)%m;int r=x;if(seen[r]==st)break;seen[r]=st;L++;}Lv[m]=L;if(L>mx){C.resize(L+1);for(int n=mx+1;n<=L;n++)C[n]=m;mx=L;}}
int last=0;for(int n=2;n<=mx;n++)if(C[n]!=last){int m=C[n],z=m,c=0;cout<<"n="<<n<<" m="<<m<<" L="<<Lv[m]<<" fac=";for(int p:ps){if(1LL*p*p>z)break;if(z%p==0){c++;cout<<p<<" ";z/=p;}}if(z>1){c++;cout<<z;}cout<<" count="<<c<<"\n";last=m;}}
